use std::io
use std::strings

fn digit_val(c: char) -> int {
    let n = c as int
    if n >= 48 && n <= 57 {
        n - 48
    } else if n >= 65 && n <= 90 {
        n - 55
    } else {
        n - 87
    }
}

fn convert(value: string, from: int, to: int) -> string {
    let mut n = 0
    for c in value.chars() {
        n = n * from + digit_val(c)
    }
    if n == 0 {
        return "0"
    }
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let mut s = ""
    while n > 0 {
        let d = n % to
        let di = d as usize
        let ch = digits[di..di + 1]
        s = "${ch}${s}"
        n = n / to
    }
    s
}

fn main() {
    loop {
        let line = io::read_line() ?? ""
        if line.len() == 0 {
            break
        }
        let parts = strings::split_whitespace(line)
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse() ?? 10
        let to: int = parts[2].parse() ?? 10
        println(convert(parts[0], from, to))
    }
}

